# Strategy: generate a large pool with specific GC patterns and screen with batch_fold
# At key positions, use fixed identity to prevent alternative helices

def gen_candidate():
    seq = ['A'] * N

    # All target pairs: use G-C for strength
    for i in range(N):
        if i in pairs and i < pairs[i]:
            j = pairs[i]
            # Vary pair types: GC, CG, AU, UA, GU, UG
            r = random.random()
            if r < 0.35:
                seq[i] = 'G'; seq[j] = 'C'
            elif r < 0.55:
                seq[i] = 'C'; seq[j] = 'G'
            elif r < 0.75:
                seq[i] = 'A'; seq[j] = 'U'
            elif r < 0.85:
                seq[i] = 'U'; seq[j] = 'A'
            elif r < 0.93:
                seq[i] = 'G'; seq[j] = 'U'
            else:
                seq[i] = 'U'; seq[j] = 'G'

    # Unpaired: anti-pattern to prevent spurious helices
    # Key insight: unpaired regions should NOT be complementary to nearby unpaired regions
    for i in range(N):
        if target[i] == '.':
            r = random.random()
            if r < 0.4: seq[i] = 'A'
            elif r < 0.7: seq[i] = 'U'
            elif r < 0.85: seq[i] = 'C'
            else: seq[i] = 'G'

    return ''.join(seq)

